local function kudurru_health_txt(dr)
  if dr.rcode ~= DNSRCode.NOERROR then
    return nil
  end
  local packet = dr:getContent()
  local overlay = newDNSPacketOverlay(packet)
  for i = 0, overlay:getRecordsCountInSection(DNSSection.Answer) - 1 do
    local rec = overlay:getRecord(i)
    if rec.type == DNSQType.TXT and rec.contentLength > 1 then
      local len = string.byte(packet, rec.contentOffset + 1)
      return string.sub(packet, rec.contentOffset + 2, rec.contentOffset + 1 + len)
    end
  end
  return nil
end

local function kudurru_node_is(dr, node)
  local txt = kudurru_health_txt(dr)
  return txt ~= nil and (txt == node or string.sub(txt, 1, #node + 1) == node .. " ")
end

-- backend node-a (10.0.0.11:5353)
function kudurru_validate_a9d98037a5da5efb96bc4d1df2e21f01(dr)
  return kudurru_node_is(dr, "node-a")
end

-- client IDs (D389): one DNS label, as kudurru's own listeners accept it
local kudurru_client_id_suffix = ".dot.example.com"
local kudurru_client_id_paths = {"/dns-query"}

local function kudurru_client_id_label(s)
  if #s == 0 or #s > 63 or string.find(s, "^[A-Za-z0-9%-]+$") == nil or string.sub(s, 1, 1) == "-" or string.sub(s, -1) == "-" then
    return nil
  end
  return string.lower(s)
end

-- The ID of /<path>/<id>; ok is false for any other path below <path>.
local function kudurru_client_id_path(path)
  for _, base in ipairs(kudurru_client_id_paths) do
    if path == base then
      return nil, true
    end
    if string.sub(path, 1, #base + 1) == base .. "/" then
      local id = kudurru_client_id_label(string.sub(path, #base + 2))
      return id, id ~= nil
    end
  end
  return nil, false
end

function kudurru_client_id(dq)
  local id = nil
  local path = dq:getHTTPPath()
  if path ~= "" then
    if kudurru_client_id_paths ~= nil then
      local ok
      id, ok = kudurru_client_id_path(path)
      if not ok then
        dq:setHTTPResponse(404, "", "")
        dq.dh:setQR(true)
        return DNSAction.HeaderModify, ""
      end
    end
  elseif kudurru_client_id_suffix ~= nil then
    local name = string.lower(dq:getServerNameIndication())
    if string.sub(name, -1) == "." then
      name = string.sub(name, 1, -2)
    end
    if #name > #kudurru_client_id_suffix and string.sub(name, -#kudurru_client_id_suffix) == kudurru_client_id_suffix then
      id = kudurru_client_id_label(string.sub(name, 1, #name - #kudurru_client_id_suffix))
    end
  end
  if id ~= nil then
    dq:addProxyProtocolValue(225, id)
    dq.skipCache = true
  end
  return DNSAction.None, ""
end
